                            Ok(())
                        },
                    );
                    assert_eq!(visited, failed + 1);
                    if panic {
                        assert_eq!(result.unwrap_err().downcast_ref::<usize>(), Some(&failed));
                    } else {
                        assert_eq!(result.unwrap(), Err(failed));
                    }
                    for (entry, identity) in entries.iter().zip(expected) {
