        assert!(matches!(state, PersistentComputeUseStateV1::Quarantined));
        assert_eq!(
            exact.owner.quarantine_reason(),
            Some(Gfx942PersistentQuarantineReasonV1::CallerReportedCurrentnessLoss)
        );
    }

