        memory.primary_retain_coherent_initialization_v1(root);
        assert_eq!(memory.coherent_insertion_snapshot_v1(), before);
        assert_eq!(memory.observation(), accounting);
        assert_eq!(output.storage_identity(), identity);
    }
}

